#include "codane/codex_provider.hpp"
namespace codane { AgentResult CodexProvider::run(const AgentRequest&r,std::stop_token st){ProcessSpec p;p.argv={c.executable,"exec","--json","-"};if(!c.model.empty()){p.argv.push_back("--model");p.argv.push_back(c.model);}p.argv.insert(p.argv.end(),c.extra_argv.begin(),c.extra_argv.end());p.stdin_text="[codane-artifacts]\n";for(auto const&a:r.artifacts)p.stdin_text+=a.producer+"/"+a.path+" => "+a.resolved_path+"\n";p.stdin_text+="[codane-prompt]\n"+r.prompt;p.cwd=r.workspace.empty()?c.cwd:r.workspace;p.timeout=r.timeout.count()?r.timeout:c.timeout;p.max_stdout=c.max_stdout;p.max_stderr=c.max_stderr;p.stop=st;auto x=run_process(p);AgentResult a;a.exit_code=x.exit_code;a.signal=x.signal;a.stdout_text=std::move(x.stdout_text);a.stderr_text=std::move(x.stderr_text);a.duration=x.duration;a.stdout_truncated=x.stdout_truncated;a.stderr_truncated=x.stderr_truncated;a.status=(x.exit_code==0&&x.signal==0)?NodeState::Succeeded:NodeState::Failed;return a;} }
